/* ---------- "Rule it out": step 1 for Science 7, Science 8, and Biology ----------
   Before choosing, students cross out two answers they know are wrong. After they answer, each answer they
   ruled out gets its written reason for being wrong (every science question already has one), so the step
   teaches the science, not just the strategy. Grades 4 and 5 keep clue words. */
const RO_GRADES=new Set([17,18,19]);
function roOn(q){return !!(q&&q.type==="mc"&&RO_GRADES.has(+gradeOf())&&q.choices.length===4&&q.why&&Object.keys(q.why).length>=3)}
function roCard(q){const R=S.ro||{x:[]},n=R.x.length;
  const list=q.choices.map((c,i)=>{const l=L[i],x=R.x.includes(l);return `<button class="choice ro${x?" x":""}" data-ro="${l}" aria-pressed="${x}"><b class="l">${l}</b><div>${choiceInner(c)}${x?`<span class="tag no">${t("Ruled out")}</span>`:""}</div></button>`}).join("");
  return `<div class="card pop"><p class="note">${t("Step 1: Rule it out. Tap TWO answers you know are wrong.")}</p>
    <div class="choices one">${list}</div>
    <div class="row"><button id="ro-next" ${n===2?"":"disabled"}>${t("Now choose your answer")}</button><span class="muted">${n} ${S.lang==="es"?"de 2 descartadas":"of 2 crossed out"}</span>${kwMode()==="optional"?`<button class="ghost small" id="ro-skip">${t("Skip to answering")}</button>`:""}</div></div>`}
function wireRo(q){
  app.querySelectorAll("[data-ro]").forEach(b=>b.onclick=()=>{const l=b.dataset.ro,R=S.ro=S.ro||{x:[]};
    R.x=R.x.includes(l)?R.x.filter(v=>v!==l):[...R.x,l].slice(-2);const wy=window.scrollY;render();window.scrollTo(0,wy);const a=app.querySelector(`[data-ro="${l}"]`);if(a)a.focus({preventScroll:true})});
  const sk=document.getElementById("ro-skip");if(sk)sk.onclick=()=>{S.ro=null;S.step=2;S.kwSkip=true;S.shownAt=Date.now();render()};
  const nx=document.getElementById("ro-next");if(nx)nx.onclick=()=>{S.step=2;S.kwSkip=true;S.shownAt=Date.now();render()}}
/* step 2: answers the student ruled out stay crossed out (they can still pick one if they change their mind).
   No hints before answering: how the ruling out went is shown only after Check. */
function roMark(){if(!S.ro||!S.ro.x.length||S.step!==2)return;const q=S.q;
  app.querySelectorAll(".choices .choice[data-l]").forEach(b=>{if(S.ro.x.includes(b.dataset.l)&&!S.result)b.classList.add("ruled")});
  if(!S.result)return;const hitAns=S.ro.x.includes(q.ans),fb=app.querySelector(".fb.go, .fb.oops");if(!fb)return;
  if(!S.ro.counted){S.ro.counted=true;const pr=S.student.prog;pr.ro=pr.ro||{n:0,ok:0};pr.ro.n++;if(!hitAns)pr.ro.ok++}
  const wrongs=S.ro.x.filter(l=>l!==q.ans);
  const d=document.createElement("div");d.className="ro-sum";d.innerHTML=hitAns?`<p><b>${t("Rule it out:")}</b> ${S.lang==="es"?`Descartaste ${q.ans}, que es la respuesta correcta. Antes de descartar, pregúntate: ¿puedo probar que está mal?`:`You crossed out ${q.ans}, the right answer. Before you rule one out, ask: can I prove it is wrong?`}</p>`
    :`<p><b>${t("Rule it out:")}</b> ${S.lang==="es"?"¡Bien! Las dos que descartaste están mal:":"Good thinking! Both answers you crossed out are wrong:"}</p><ul>${wrongs.map(l=>`<li><b>${l}.</b> ${fmt(q.why[l]||"")}</li>`).join("")}</ul>`;
  const first=fb.querySelector("p");if(first)first.after(d);else fb.appendChild(d)}
