/* ===== ELA language question makers (original word banks) =====
   Each maker builds a fresh question from a checked word bank, so grammar and vocabulary practice does not repeat.
   ELGEN(strand, grades, weight, fn): weight = how many slots the maker gets in a student's deck. */
{
const NAMES=["Maya","Jalen","Rosa","Kenji","Amara","Luis","Tia","Marcus","Lena","Omar","Priya","Darius","Ava","Ben","Zoe","Caleb"];
const cap=s=>s[0].toUpperCase()+s.slice(1);
/* ---------- L.1: subject–verb agreement (grades 3–5) ---------- */
const SING=["My sister","The teacher","Our coach","The bus driver","The farmer","My best friend","The nurse","My uncle","The student","Our neighbor"],
  PLUR=["My sisters","The teachers","Our coaches","The bus drivers","The farmers","My best friends","The nurses","My uncles","The students","Our neighbors"],
  VERBS=[["walks","walk","walking","walked"],["sings","sing","singing","sang"],["reads","read","reading","readed"],["runs","run","running","ran"],["cooks","cook","cooking","cooked"],["writes","write","writing","wrote"],["swims","swim","swimming","swam"],["plays","play","playing","played"],["waits","wait","waiting","waited"],["helps","help","helping","helped"]],
  ENDS=["every morning.","after school every day.","on Saturdays.","each evening.","every weekend.","before dinner each night."];
ELGEN("L.1",[3,4,5],10,(r,o)=>{const pl=r()<.5,s=o.pick(r,pl?PLUR:SING),v=o.pick(r,VERBS),end=o.pick(r,ENDS),right=pl?v[1]:v[0],wrong=pl?v[0]:v[1];
  const rule=pl?"A plural subject takes a verb without -s.":"A singular subject takes a verb that ends in -s.";
  return {stem:`Which verb correctly completes the sentence?\n${s} ____ ${end}`,right,w:[[wrong,rule],[v[2],"An -ing verb needs a helping verb like is or are."],[(pl?"is ":"are ")+v[2],pl?"“Is” goes with one person or thing. This subject is more than one.":"“Are” goes with more than one. This subject is just one."]],steps:`Find the subject: “${s.toLowerCase().replace(/^the |^my |^our |^a |^two /,"")}”. Is it one or more than one?|${rule}`,x:{k:"verb correctly completes"}}});
/* ---------- L.1: irregular past tense (grades 3–5) ---------- */
const IRR=[["go","went","goed","gone","to the store"],["eat","ate","eated","eaten","a big breakfast"],["see","saw","seed","seen","a rainbow"],["take","took","taked","taken","the bus"],["write","wrote","writed","written","a letter"],["ride","rode","rided","ridden","a bike"],["sing","sang","singed","sung","a song"],["swim","swam","swimmed","swum","across the pool"],["throw","threw","throwed","thrown","the ball"],["drink","drank","drinked","drunk","a glass of milk"],["give","gave","gived","given","a gift"],["fly","flew","flied","flown","a kite"],["draw","drew","drawed","drawn","a picture"],["break","broke","breaked","broken","the record"],["bring","brought","bringed","brung","lunch"],["catch","caught","catched","catchen","a fish"],["teach","taught","teached","teachen","the class"],["sleep","slept","sleeped","sleepen","for ten hours"]],
  WHEN=["Yesterday","Last night","Last week","Two days ago","Last summer","This morning"];
ELGEN("L.1",[3,4,5],10,(r,o)=>{const v=o.pick(r,IRR),n=o.pick(r,NAMES),wh=o.pick(r,WHEN);
  return {stem:`Which verb correctly completes the sentence?\n${wh}, ${n} ____ ${v[4]}.`,right:v[1],w:[[v[2],`“${v[0]}” is irregular; its past tense is not made with -ed.`],[v[3],`“${v[3]}” needs a helping verb, like has or had.`],[v[0],`“${wh}” tells you the action is in the past.`]],steps:`“${wh}” tells you the action happened in the past.|The past tense of “${v[0]}” is “${v[1]}.”`,x:{k:wh.split(" ")[0].toLowerCase()+" verb"}}});
/* ---------- L.1: comparatives and superlatives (grades 3–4) ---------- */
const ADJ=[["tall","taller","tallest","a giraffe","a horse","animals"],["fast","faster","fastest","a cheetah","a lion","runners"],["small","smaller","smallest","a mouse","a cat","pets"],["cold","colder","coldest","January","March","months"],["long","longer","longest","the river","the creek","trails"],["heavy","heavier","heaviest","the rock","the pebble","boxes"],["happy","happier","happiest","Maya","her brother","kids at the party"],["big","bigger","biggest","the elephant","the zebra","animals at the zoo"],["loud","louder","loudest","the drum","the flute","instruments"],["early","earlier","earliest","the 7:00 bus","the 8:00 bus","buses"]];
ELGEN("L.1",[3,4],8,(r,o)=>{const a=o.pick(r,ADJ),two=r()<.5;
  if(two)return {stem:`Which word correctly completes the sentence?\n${cap(a[3])} is ____ than ${a[4]}.`,right:a[1],w:[[a[2],"Use -est only when comparing three or more."],["more "+a[1],"Never use more with an -er word."],[a[0],"When you compare two things, add -er."]],steps:"Two things are being compared.|Use the -er form: “"+a[1]+".”",x:{k:"than"}};
  return {stem:`Which word correctly completes the sentence?\nOf all the ${a[5]}, this one is the ____.`,right:a[2],w:[[a[1],"Use -er only when comparing two things."],["most "+a[2],"Never use most with an -est word."],[a[0],"When you compare three or more, add -est."]],steps:"“Of all” means three or more are compared.|Use the -est form: “"+a[2]+".”",x:{k:"of all"}}});
/* ---------- L.1: pronoun case (grades 6–8) ---------- */
const PRO=[["I","me","myself","mine"],["he","him","himself","his"],["she","her","herself","hers"],["we","us","ourselves","ours"],["they","them","themselves","theirs"]],
  SUBJ_T=[n=>`${n} and ____ finished the science project.`,n=>`${n} and ____ won the spelling bee.`,n=>`${n} and ____ walked to the game together.`,n=>`${n} and ____ are on the same team.`],
  OBJ_T=[n=>`The coach handed the trophy to ${n} and ____.`,n=>`Mom drove ${n} and ____ to practice.`,n=>`The teacher asked ${n} and ____ to help.`,n=>`Between ${n} and ____, the job was easy.`];
ELGEN("L.1",[6,7,8],12,(r,o)=>{const p=o.pick(r,PRO),n=o.pick(r,NAMES),subj=r()<.5,t=o.pick(r,subj?SUBJ_T:OBJ_T)(n);
  const right=subj?p[0]:p[1],wrong=subj?p[1]:p[0],stem=t.startsWith("____")?t.replace("____",cap(right)==="I"?"____":"____"):t;
  const fix=x=>t.startsWith("____")&&x!=="I"?cap(x):x;
  return {stem:`Which pronoun correctly completes the sentence?\n${stem}`,right:fix(right),w:[[fix(wrong),subj?"The pronoun is part of the subject, so use a subject pronoun.":"The pronoun is an object (after a verb or preposition), so use an object pronoun."],[fix(p[2]),"A -self pronoun needs a matching word earlier in the sentence."],[fix(p[3]),"That is a possessive pronoun; it shows ownership."]],steps:`Try the sentence with only the pronoun.|${subj?"It is part of the subject":"It is an object"}, so use “${right}.”`,x:{k:"pronoun"}}});
/* ---------- L.2: commas in a series (grades 4–6) ---------- */
const SERIES=[[["apples","grapes","bananas"],["bought","packed","likes"]],[["a pencil","a ruler","an eraser"],["packed","bought","needs"]],[["Jackson","Biloxi","Tupelo"],["visited"]],[["red","white","blue"],["likes"]],[["soccer","swimming","track"],["likes","plays"]],[["the lake","the forest","the beach"],["visited"]],[["milk","eggs","bread"],["bought"]],[["a hammer","nails","a saw"],["packed","needs","bought"]],[["a tent","a lantern","sleeping bags"],["packed","bought","needs"]]];
ELGEN("L.2",[4,5,6],10,(r,o)=>{const [items,verbs]=o.pick(r,SERIES),[a,b,c]=o.shuf(r,items),n=o.pick(r,NAMES),L=`${n} ${o.pick(r,verbs)}`;
  return {stem:"Which sentence uses commas correctly?",right:`${L} ${a}, ${b}, and ${c}.`,w:[[`${L} ${a} ${b} and ${c}.`,"Items in a series of three or more need commas between them."],[`${L}, ${a}, ${b}, and ${c}.`,"Do not put a comma between the verb and the list."],[`${L} ${a}, ${b}, and, ${c}.`,"Do not put a comma after “and.”"]],steps:"Use commas to separate three or more items in a series.|No comma comes before the list or after “and.”",x:{k:"commas correctly"}}});
/* ---------- L.2: capitalization of proper nouns (grades 3–5) ---------- */
const PLACES=[["Vicksburg","Mississippi River"],["Oxford","Ole Miss campus"],["Natchez","Natchez Trace"],["Memphis","Mississippi River"],["New Orleans","French Quarter"],["Gulfport","Gulf of Mexico"]],
  MONTHS=["January","March","April","June","July","October","November"],DAYS=["Monday","Tuesday","Thursday","Friday","Saturday"];
ELGEN("L.2",[3,4,5],8,(r,o)=>{const n=o.pick(r,NAMES),[city]=o.pick(r,PLACES),m=o.pick(r,MONTHS),d=o.pick(r,DAYS);
  const right=`On ${d}, ${n} will visit ${city} in ${m}.`;
  return {stem:"Which sentence uses capital letters correctly?",right,w:[[`On ${d.toLowerCase()}, ${n} will visit ${city} in ${m.toLowerCase()}.`,"Days of the week and months are proper nouns, so they are capitalized."],[`On ${d}, ${n} will visit ${city.toLowerCase()} in ${m}.`,"Names of cities are proper nouns, so they are capitalized."],[`On ${d}, ${n} Will Visit ${city} In ${m}.`,"Ordinary words like will, visit, and in are not capitalized."]],steps:"Capitalize names of people, places, days, and months.|Do not capitalize ordinary words in the middle of a sentence.",x:{k:"capital letters"}}});
/* ---------- L.4: prefixes (grades 3–5) ---------- */
const PRE=[["un",w=>`not ${w}`,["happy","kind","safe","fair","tidy","lucky","able"]],["re",w=>`${w} again`,["write","build","fill","paint","read","tell","heat","use"]],["pre",w=>`${w} before`,["heat","view","pay","cook","test","wash"]],["mis",w=>`${w} wrongly`,["spell","read","count","judge","place","label"]]],
  PRE_EX={un:{happy:"unhappy",kind:"unkind",safe:"unsafe",fair:"unfair",tidy:"untidy",lucky:"unlucky",able:"unable"}};
ELGEN("L.4",[3,4,5],10,(r,o)=>{const i=Math.floor(r()*PRE.length),[px,mean,bases]=PRE[i],b=o.pick(r,bases),word=px+b;
  const others=PRE.filter((_,j)=>j!==i).map(x=>x[1](b));
  return {stem:`The prefix “${px}-” is added to “${b}.” What does the word “${word}” mean?`,right:mean(b),w:others.map(m=>[m,`That meaning goes with a different prefix. “${px}-” means ${{un:"not",re:"again",pre:"before",mis:"wrongly"}[px]}.`]),steps:`Split the word: ${px} + ${b}.|“${px}-” ${px==="un"?"means not":px==="re"?"means again":px==="pre"?"means before":"means wrongly"}, so “${word}” means “${mean(b)}.”`,x:{k:word}}});
/* ---------- L.4: suffixes (grades 3–5) ---------- */
const SUF=[["ful",w=>`full of ${w}`,["hope","care","fear","joy","help","color","thank","pain","use"]],["less",w=>`without ${w}`,["hope","care","fear","help","color","home","pain","use","spot"]]];
ELGEN("L.4",[3,4,5],8,(r,o)=>{const i=Math.floor(r()*SUF.length),[sx,mean,bases]=SUF[i],b=o.pick(r,bases),word=b+sx,other=SUF[1-i][1](b),d=sx==="ful"?"full of":"without";
  return {stem:`The suffix “-${sx}” is added to “${b}.” What does the word “${word}” mean?`,right:mean(b),w:[[other,`That is the meaning of “${b}${SUF[1-i][0]}.” “-${sx}” means ${d}.`],[`${b} again`,`“Again” goes with the prefix re-. “-${sx}” means ${d}.`],[`before ${b}`,`“Before” goes with the prefix pre-. “-${sx}” means ${d}.`]],steps:`Split the word: ${b} + ${sx}.|“-${sx}” means ${d}, so “${word}” means “${mean(b)}.”`,x:{k:word}}});
/* ---------- L.4: Greek and Latin roots (grades 6–8) ---------- */
const ROOTS=[["bio","life","biology"],["geo","earth","geography"],["tele","far","telescope"],["photo","light","photograph"],["graph","write","autograph"],["aud","hear","audience"],["vis","see","visible"],["port","carry","portable"],["dict","say","dictionary"],["rupt","break","erupt"],["struct","build","structure"],["spect","look","spectator"],["chron","time","chronology"],["therm","heat","thermometer"],["aqua","water","aquarium"],["micro","small","microscope"]];
ELGEN("L.4",[6,7,8],10,(r,o)=>{const k=Math.floor(r()*ROOTS.length),[root,mean,ex]=ROOTS[k],w=o.shuf(r,ROOTS.filter((_,j)=>j!==k)).slice(0,3);
  return {stem:`The word “${ex}” contains the root “${root}.” What does “${root}” mean?`,right:mean,w:w.map(x=>[x[1],`“${x[1]}” is the meaning of the root “${x[0]},” as in “${x[2]}.”`]),steps:`Think of other words with “${root}.”|“${root}” means “${mean},” as in “${ex}.”`,x:{k:root}}});
/* ---------- L.5: synonyms and antonyms (grades 4–6) ---------- */
const SYN=[["brave","courageous","fearful"],["rapid","quick","slow"],["ancient","old","modern"],["enormous","huge","tiny"],["happy","cheerful","gloomy"],["difficult","hard","easy"],["calm","peaceful","nervous"],["begin","start","finish"],["often","frequently","rarely"],["purchase","buy","sell"],["generous","giving","selfish"],["silent","quiet","noisy"],["damp","moist","dry"],["error","mistake","correction"],["assist","help","hinder"],["polite","courteous","rude"]];
ELGEN("L.5",[4,5,6],10,(r,o)=>{const k=Math.floor(r()*SYN.length),[w,syn,ant]=SYN[k],asSyn=r()<.5,others=o.shuf(r,SYN.filter((_,j)=>j!==k)).slice(0,2).map(x=>x[1]);
  return asSyn?{stem:`Which word is a SYNONYM for “${w}”?`,right:syn,w:[[ant,`“${ant}” means the opposite of “${w}”: it is an antonym.`],...others.map(x=>[x,`“${x}” does not mean the same as “${w}.”`])],steps:`A synonym means nearly the same.|“${syn}” means about the same as “${w}.”`,x:{k:"synonym"}}
   :{stem:`Which word is an ANTONYM for “${w}”?`,right:ant,w:[[syn,`“${syn}” means about the same as “${w}”: it is a synonym.`],...others.map(x=>[x,`“${x}” is not the opposite of “${w}.”`])],steps:`An antonym means the opposite.|“${ant}” is the opposite of “${w}.”`,x:{k:"antonym"}}});
}

/* ===== L.6: acquire and use grade-appropriate academic and domain-specific words (2025 MS CCRS) =====
   Grade 3: words that signal time and place. Grade 4: precise action, feeling, and topic words.
   Grade 5: words that signal contrast, addition, and other logical relationships.
   Grades 6–8: general academic and domain-specific words used accurately in context.
   Every item is original; each wrong choice says why it does not fit. */
/* ---------- grade 3: time and place words ---------- */
ELQ("L.6",[3],"Which word in the sentence tells WHEN it happened?\nAfter lunch, we planted seeds in the garden.","After","planted~“Planted” is the action, what we did.","seeds~“Seeds” names a thing.","garden~“Garden” tells where, not when.","Look for a word that tells time: before, after, during, then, later.|“After lunch” tells when.");
ELQ("L.6",[3],"Which word tells WHERE the cat was hiding?\nThe cat was hiding beneath the porch.","beneath","was~“Was” is a helping verb.","hiding~“Hiding” is the action.","cat~“Cat” tells who.","Place words tell where: under, beneath, beside, above, behind.|“Beneath the porch” tells where.");
ELQ("L.6",[3],"Choose the word that best completes the sentence.\nWe finished our homework. ____, we went outside to play.","Then","Before~“Before” would mean we played first, but the homework was finished first.","Under~“Under” tells where, not when.","Because~“Because” gives a reason. This sentence tells what happened next.","The sentences tell events in order.|“Then” tells what happened next.");
ELQ("L.6",[3],"Which word in the sentence tells WHEN?\nDuring the storm, the lights flickered.","During","storm~“Storm” names the event.","lights~“Lights” names a thing.","flickered~“Flickered” is the action.","“During” means while something is happening.|It tells when the lights flickered.");
ELQ("L.6",[3],"Which phrase tells WHERE Mom put the keys?\nAfter school, Mom put the keys beside the lamp.","beside the lamp","After school~“After school” tells when, not where.","Mom put~“Mom put” tells who and what she did.","the keys~“The keys” tells what she put down.","Ask: where did the keys go?|“Beside the lamp” tells where.");
ELQ("L.6",[3],"Choose the word that best completes the sentence.\nPlease wash your hands ____ you eat.","before","after~Washing should come first, so “after” is the wrong order.","above~“Above” tells where, not when.","because~“Because” gives a reason, but this sentence tells when.","Think about the order: wash, then eat.|“Before” tells what comes first.");
ELQ("L.6",[3],"Which phrase tells WHERE the robin built its nest?\nEarly that morning, a robin built a nest high in the oak tree.","high in the oak tree","Early that morning~“Early that morning” tells when, not where.","a robin built~“A robin built” tells who and what it did.","built a nest~“Built a nest” is the action.","Look for words that name a place.|“High in the oak tree” tells where.");
ELQ("L.6",[3],"Which word in the sentence tells WHEN?\nYesterday, our class visited the fire station.","Yesterday","class~“Class” tells who.","visited~“Visited” is the action.","station~“Station” tells where.","“Yesterday” means the day before today.|It tells when.");
ELQ("L.6",[3],"Choose the word that best completes the sentence.\nThe dog crawled ____ the fence to get into the yard.","under","later~“Later” tells when, not where.","soon~“Soon” tells when, not where.","first~“First” tells order, not where.","The dog moved to a place.|“Under the fence” tells where it crawled.");
ELQ("L.6",[3],"What does “meanwhile” mean in the sentence?\nDad cooked dinner. Meanwhile, I set the table.","at the same time","a long time ago~Both things happened during dinner time, not long ago.","in a different place~“Meanwhile” is about time, not place.","because of that~“Meanwhile” does not give a reason.","Dad cooked while I set the table.|“Meanwhile” means at the same time.");
ELQ("L.6",[3],"Which word tells WHERE the ball rolled?\nThe ball rolled across the street.","across","ball~“Ball” is the thing that rolled.","rolled~“Rolled” is the action.","the~“The” is a small word that points to a noun.","“Across” means from one side to the other.|It tells where the ball went.");
ELQ("L.6",[3],"Choose the word that best completes the sentence.\nFirst, mix the flour and eggs. ____, pour the batter into the pan.","Next","Before~“Before” would put pouring ahead of mixing.","Inside~“Inside” tells where, not order.","Yesterday~“Yesterday” tells a day, not the next step.","Steps in order: first, next, then, last.|“Next” tells the second step.");
ELQ("L.6",[3],"Which word in the sentence tells WHEN?\nAt sunset, the frogs began to sing.","sunset","frogs~“Frogs” tells who.","began~“Began” is part of the action.","sing~“Sing” is the action.","Sunset is a time of day.|“At sunset” tells when.");
ELQ("L.6",[3],"Which phrase tells WHERE the students lined up?\nEvery Monday morning, the students lined up outside the library.","outside the library","Every Monday morning~“Every Monday morning” tells when, not where.","the students~“The students” tells who.","lined up~“Lined up” is the action.","Ask: where did the students line up?|“Outside the library” tells where.");
/* ---------- grade 4: precise words and topic words ---------- */
ELQ("L.6",[4],"Which word best shows that Leo was nervous when he spoke?\nLeo ____, “I-I think I forgot my lines.”","stammered","shouted~“Shouted” shows loud talking, not nervous talking.","announced~“Announced” sounds confident.","laughed~“Laughed” shows he was amused.","The dialogue repeats “I-I,” which shows nervous speech.|“Stammered” means spoke with pauses or repeats.");
ELQ("L.6",[4],"Which word best shows that the child was complaining?\n“I don’t want to clean my room,” the child ____.","whined","whispered~“Whispered” tells how quietly, not that he complained.","cheered~“Cheered” shows happiness.","explained~“Explained” means gave reasons calmly.","The child does not want to do the chore.|“Whined” means complained in an unhappy voice.");
ELQ("L.6",[4],"What does “quizzed” mean in the sentence?\nThe coach quizzed the players on the new plays before the game.","asked questions to check what they knew","gave each player a prize for winning~A quiz checks knowledge; it is not a prize.","yelled at them for making mistakes~Nothing shows the coach was angry.","taught them the plays for the first time~The plays were already learned; the coach was checking.","A quiz is a short test.|To quiz someone is to ask questions to check what they know.");
ELQ("L.6",[4],"Which word best tells how the tired hiker moved?\nAfter ten miles, the hiker ____ up the last hill.","trudged","skipped~“Skipped” shows a happy, light step.","raced~“Raced” shows speed and energy.","bounced~“Bounced” shows energy, not tiredness.","The hiker was tired after ten miles.|“Trudged” means walked slowly and heavily.");
ELQ("L.6",[4],"When a class talks about protecting animals, which word means a kind of animal that could soon disappear forever?","endangered","domestic~“Domestic” means tame, like pets and farm animals.","nocturnal~“Nocturnal” means active at night.","migrating~“Migrating” means moving from place to place with the seasons.","Animals at risk of dying out are endangered.|Conservation work helps endangered animals.");
ELQ("L.6",[4],"What does “conservation” mean in the sentence?\nThe park’s conservation program protects the wetlands and the birds that live there.","protecting nature and wildlife","building new roads through the park~Roads would harm the wetlands, not protect them.","hunting the animals that live there~Hunting is the opposite of protecting.","visiting the park on weekends~Visiting is not the same as protecting.","The sentence says the program protects wetlands and birds.|Conservation is protecting nature.");
ELQ("L.6",[4],"Which word best shows that Maya was very happy?\nMaya ____ when she saw her grandmother at the airport.","beamed","frowned~“Frowned” shows she was unhappy.","shrugged~“Shrugged” shows she did not care.","sighed~A sigh often shows she was tired or sad.","Seeing a loved one usually makes people happy.|“Beamed” means smiled widely.");
ELQ("L.6",[4],"Which word best describes a person who is very afraid?","terrified","annoyed~“Annoyed” means a little angry.","curious~“Curious” means wanting to know more.","proud~“Proud” means pleased with yourself.","Some words show strong feelings.|“Terrified” means very afraid.");
ELQ("L.6",[4],"What does “habitat” mean in the sentence?\nThe frog’s habitat is a warm, wet pond full of insects to eat.","the natural home of a plant or animal","the kind of food an animal eats~Insects are the food; the pond is the home.","a large group of the same animal~A group of frogs is not called a habitat.","the way an animal moves around~Habitat is a place, not a way of moving.","The sentence describes where the frog lives.|A habitat is a natural home.");
ELQ("L.6",[4],"Which word best tells how the thief left the room?\nThe thief ____ out of the room without making a sound.","crept","stomped~Stomping is loud.","marched~Marching is loud and in step.","stumbled~Stumbling is clumsy and could make noise.","The thief made no sound.|“Crept” means moved slowly and quietly.");
ELQ("L.6",[4],"Which word best shows that Jalen was surprised?\nJalen ____ when the box began to move.","gasped","yawned~A yawn shows he was sleepy.","giggled~A giggle shows he thought something was funny.","grumbled~Grumbling shows he was unhappy.","A box moving by itself is surprising.|“Gasped” means breathed in suddenly from surprise.");
ELQ("L.6",[4],"What does “predator” mean in the sentence?\nThe hawk is a predator that hunts mice and snakes.","an animal that hunts other animals for food","an animal that is hunted~That is called prey.","an animal that eats only plants~The hawk hunts mice and snakes.","a baby animal~Nothing in the sentence is about babies.","The sentence says the hawk hunts mice and snakes.|A predator hunts other animals.");
/* ---------- grade 5: words that signal logical relationships ---------- */
ELSET("L.6",[5],"Choose the word or phrase that best completes the sentences.","These words connect ideas: however and although show contrast; moreover and in addition add more; therefore and as a result show cause and effect; similarly shows a likeness.",[
 ["The forecast said it would be sunny. ____, it rained all afternoon.","However","Moreover","Similarly","For example"],
 ["Kenji practices piano every day. ____, he takes lessons on Saturdays.","In addition","However","Nevertheless","Instead"],
 ["The bridge was closed for repairs. ____, we had to take a longer road.","As a result","Similarly","Moreover","Although"],
 ["Rosa was tired after the game. ____, she finished all her homework.","Nevertheless","Therefore","Similarly","In addition"],
 ["Bees help flowers make seeds by moving pollen. ____, butterflies carry pollen from flower to flower.","Similarly","However","Instead","As a result"],
 ["Our school recycles paper. ____, it collects cans and bottles.","Moreover","However","Nevertheless","Instead"],
 ["____ the trail was steep, the hikers reached the top.","Although","Because","Therefore","Moreover"],
 ["The library will close early on Friday. ____, return your books by Thursday.","Therefore","However","Similarly","Although"]]);
ELQ("L.6",[5],"What does “nevertheless” show in the sentence?\nThe puzzle was hard. Nevertheless, Amara solved it in ten minutes.","She solved it even though it was hard.","It adds a second example of a puzzle.~Nevertheless does not add an example.","The hard puzzle is why she solved it.~The hard puzzle did not cause her to solve it.","It shows two puzzles that are alike.~Nevertheless does not compare.","A hard puzzle might stop someone.|“Nevertheless” means she solved it anyway.");
ELQ("L.6",[5],"Which word signals that the writer is adding more information?\nSoccer builds strong muscles. Furthermore, it teaches players teamwork.","Furthermore","muscles~“Muscles” is a noun.","teaches~“Teaches” is a verb, not a connecting word.","teamwork~“Teamwork” is a noun.","Some words join ideas.|“Furthermore” means also, in addition.");
ELQ("L.6",[5],"Which word in the sentence signals a contrast?\nWhales live in the ocean, but they breathe air like land animals.","but","live~“Live” is a verb.","like~“Like” shows a comparison of how they are alike.","ocean~“Ocean” is a place.","A contrast shows a difference.|“But” sets two different ideas side by side.");
ELQ("L.6",[5],"Which word signals cause and effect?\nThe soil stayed completely dry; consequently, the tomato plants wilted.","consequently","completely~“Completely” tells how dry the soil was.","plants~“Plants” is a noun.","wilted~“Wilted” is the effect itself, not the signal word.","Cause: dry soil. Effect: wilted plants.|“Consequently” means as a result.");
ELQ("L.6",[5],"Which word best completes the sentence?\nSome reptiles live in deserts, ____ others live in rain forests.","whereas","because~“Because” gives a reason; this sentence contrasts two places.","therefore~“Therefore” shows a result.","moreover~“Moreover” adds a similar point.","Deserts and rain forests are being contrasted.|“Whereas” shows a contrast.");
ELQ("L.6",[5],"What does “for instance” do in the sentence?\nMany animals change color with the seasons. For instance, the arctic fox turns white in winter.","It introduces an example.","It shows a contrast.~The fox agrees with the first sentence; it does not contrast.","It shows the end of a list.~It begins an example, not the end of a list.","It shows a time order.~It does not tell when, it gives an example.","The second sentence gives one animal that changes color.|“For instance” means for example.");
/* ---------- grades 6–8: general academic and domain-specific words ---------- */
ELSET("L.6",[6,7,8],"Choose the word that best completes the sentence.","Academic words have exact meanings. Read the whole sentence and choose the word whose meaning fits.",[
 ["To ____ the two stories, Omar listed how the main characters were alike and how they were different.","compare","summarize","predict","illustrate"],
 ["Before the experiment, Lena wrote a ____: “Plants given more sunlight will grow taller.”","hypothesis","conclusion","summary","variable"],
 ["The author does not say Tia is jealous, but readers can ____ it from her actions.","infer","quote","cite","define"],
 ["In her essay, Priya will ____ the article by giving its title, author, and page number.","cite","infer","predict","revise"],
 ["The scientist changed only one ____ at a time so she could see what caused the change.","variable","conclusion","theory","summary"],
 ["To ____ the chapter, Darius wrote three sentences that told only the most important ideas.","summarize","analyze","predict","contrast"]]);
ELQ("L.6",[6,7,8],"What does “analyze” mean in the sentence?\nThe class will analyze the poem by looking closely at each stanza and how it builds the mood.","to study each part closely to understand it","to copy the poem out word for word~Copying is not studying the parts.","to guess what will happen in the next poem~That is predicting.","to retell the poem in fewer words~That is summarizing.","The class looks closely at each part.|Analyze means study the parts to understand the whole.");
ELQ("L.6",[6,7,8],"What does “evidence” mean in the sentence?\nUse evidence from the text to support your answer.","facts or details that show something is true","your own opinion about the topic~An opinion is not proof from the text.","the title and author of the text~The title alone does not support an answer.","a question you have about the text~A question does not prove anything.","Support means prove or back up.|Evidence is the details that back up an answer.");
ELQ("L.6",[6],"Which word means the people who live in a place, such as a town or country?","population","climate~Climate is the usual weather of a place.","government~Government is the group that runs a place and makes laws.","economy~An economy is how goods and money move.","Social studies words have exact meanings.|Population is the people who live in a place.");
ELQ("L.6",[6,7],"What does “ratio” mean in the sentence?\nThe ratio of boys to girls in the class is 3 to 4.","a comparison of two amounts","a total of two amounts~3 and 4 are compared, not added.","the difference between two amounts~A ratio does not subtract.","a guess about an amount~A ratio is exact, not a guess.","A ratio compares one amount to another.|3 to 4 compares boys to girls.");
ELQ("L.6",[7,8],"What does “bias” mean in the sentence?\nThe article showed bias because it gave only one side of the debate.","an unfair leaning toward one side","a fact that can be checked~Bias is not a checked fact.","a short summary~A summary is not bias.","a reliable source~Giving only one side is not reliable.","The article gave only one side.|Bias is leaning unfairly toward one side.");
ELQ("L.6",[7,8],"What does “photosynthesis” mean in the sentence?\nThrough photosynthesis, plants use sunlight, water, and carbon dioxide to make sugar.","the process plants use to make food from sunlight","the way plants take in water from the soil~That is only one part; photosynthesis makes sugar.","the way animals break down food~Photosynthesis happens in plants.","the way seeds travel to new places~That is seed dispersal.","The sentence lists what plants use and what they make.|Photosynthesis is how plants make food using light.");
ELQ("L.6",[7,8],"Which word best completes the sentence?\nThe senator tried to ____ voters that the new law would help small businesses.","persuade","describe~Describing does not try to change minds.","narrate~Narrating means telling a story.","summarize~Summarizing gives the main points.","The senator wants voters to agree.|Persuade means convince someone to believe or do something.");
ELQ("L.6",[8],"What does “credible” mean in the sentence?\nA government health website is a more credible source than an anonymous blog.","believable and trustworthy","easy to read~Being easy to read does not make a source trustworthy.","very long~Length does not decide whether a source is credible.","written by students~Who wrote it matters, but student writing is not the meaning.","The government website is compared with an anonymous blog.|Credible means believable and trustworthy.");
ELQ("L.6",[8],"Which word best completes the sentence?\nThe writer’s claim is strong because she supports it with ____ evidence from three studies.","relevant","irrelevant~Irrelevant evidence does not connect to the claim.","imaginary~Imaginary evidence is not evidence.","biased~Biased evidence weakens a claim.","Strong claims need evidence that connects to them.|Relevant means closely connected to the point.");
ELQ("L.6",[6,7,8],"What does “justify” mean in the direction?\nJustify your answer with two details from the passage.","give reasons that show why it is right","change your answer to a better one~Justify keeps the answer and supports it.","rewrite your answer more neatly~Justify is about reasons, not handwriting.","make your answer a little shorter~Justify adds support, not cuts.","Two details will support the answer.|Justify means give reasons that prove it.");
ELQ("L.6",[6,7,8],"What does “sequence” mean in the sentence?\nThe article explains the sequence of events that led to the flood.","the order in which things happen","the cause of one event~A sequence is the order, not one cause.","a list of people involved~People are not the sequence.","a guess about the future~The flood already happened.","Events that led to the flood happened one after another.|Sequence means order.");

