/* ---------- ELA: register reading and language standards as trail skills (course keys 23–28) ---------- */
const ELA_GRADES=[23,24,25,26,27,28];
const ELA_STR={
 "RL.1":["Text evidence in stories","Answer questions about a story or poem and point to the part of the text that supports the answer.","Ask and answer questions, refer to details, quote accurately, or cite the strongest evidence for what a literary text says and what it suggests."],
 "RL.2":["Theme and summary","Find the lesson, message, or theme of a story or poem and tell how the details build it.","Determine a theme or central message, explain how key details convey it, and summarize the text."],
 "RL.3":["Characters, settings, and events","Describe characters and explain how their traits, choices, and words move the story along.","Describe or analyze characters, settings, and events, and how they interact or drive the plot."],
 "RL.4":["Word meaning in stories and poems","Work out what words and phrases mean in a story or poem, including figurative language.","Determine the meaning of words and phrases as they are used in a literary text, and how word choice shapes meaning and tone."],
 "RL.5":["Story and poem structure","Explain how the parts of a story or poem (chapters, scenes, stanzas) fit together and build on each other.","Refer to and analyze the structure of stories, dramas, and poems and how each part contributes to the whole."],
 "RL.6":["Point of view in stories","Tell who is telling the story and how the narrator’s or characters’ points of view shape it.","Distinguish, compare, or analyze the points of view of narrators, characters, and readers."],
 "RI.1":["Text evidence in informational text","Answer questions about an informational text and point to the part of the text that supports the answer.","Ask and answer questions, refer to details, quote accurately, or cite the strongest evidence for what an informational text says and what it suggests."],
 "RI.2":["Main idea and key details","Find the main or central idea of a text and explain how the key details support it.","Determine the main or central idea, explain how details support it, and summarize the text."],
 "RI.3":["Connecting people, events, and ideas","Explain how people, events, steps, or ideas in a text are connected, such as cause and effect or sequence.","Describe or analyze the relationships and interactions among individuals, events, ideas, or steps in a text."],
 "RI.4":["Word meaning in informational text","Work out what general academic and subject-area words and phrases mean in a text.","Determine the meaning of words and phrases as they are used in an informational text, including figurative and technical meanings."],
 "RI.5":["Text features and structure","Use text features and explain how a text is organized (sequence, comparison, cause and effect, problem and solution).","Use text features and analyze how sections, paragraphs, and overall structure develop the ideas."],
 "RI.6":["Author’s point of view and purpose","Tell the author’s point of view or purpose and how it shapes what the text says.","Determine an author’s point of view or purpose and how the author conveys it or responds to other viewpoints."],
 "RI.8":["Reasons and evidence","Explain how an author uses reasons and evidence to support points, and judge whether the support is strong.","Describe, explain, trace, or evaluate the reasons and evidence an author gives to support particular points or claims."],
 "L.1":["Grammar and usage","Use the grammar rules for this grade when choosing words and building sentences.","Demonstrate command of the conventions of standard English grammar and usage."],
 "L.2":["Capitalization, punctuation, and spelling","Use capital letters, punctuation marks, and spelling correctly.","Demonstrate command of the conventions of standard English capitalization, punctuation, and spelling."],
 "L.4":["Unknown words: context and word parts","Figure out what an unknown or multiple-meaning word means by using context clues, prefixes, suffixes, and roots.","Determine or clarify the meaning of unknown and multiple-meaning words using context, affixes and roots, and reference materials."],
 "L.6":["Academic and subject-area words","Use the exact words for this grade: time and place words (grade 3), precise action, feeling, and topic words (grade 4), linking words like however and moreover (grade 5), and academic and subject words (grades 6–8).","Acquire and use accurately grade-appropriate general academic and domain-specific words and phrases."],
 "L.5":["Figurative language and word relationships","Understand figurative language, how words relate to each other, and small differences in word meanings.","Demonstrate understanding of figurative language, word relationships, and nuances in word meanings."]};
(()=>{const dn={RL:"Reading Literature",RI:"Reading Informational Text",L:"Language"};
  [3,4,5,6,7,8].forEach(g=>Object.keys(ELA_STR).forEach(s=>{const [a,n]=s.split("."),code=`${a}.${g}.${n}`,gen="e"+code.toLowerCase().replace(/\./g,""),v=ELA_STR[s];
    if(!GENELA.pool(code).length)return;
    const x={code,grade:20+g,dom:"ELA-"+a,name:v[0],gen,desc:v[1],know:[v[2]],und:[],do:[v[1]]};
    LIB.push(x);LIBC[code]=x;LIBG[gen]=x;ELA_CODE[gen]=code;
    if(g>3&&LIBC[`${a}.${g-1}.${n}`])PREQ[code]=[`${a}.${g-1}.${n}`]}));
  Object.assign(DOMS,{"ELA-RL":dn.RL,"ELA-RI":dn.RI,"ELA-L":dn.L})})();
ELA_GRADES.forEach(g=>{if(!GRADES.includes(g))GRADES.push(g)});
